package com.docgen.service

import io.ktor.server.application.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import kotlinx.serialization.*
import kotlinx.serialization.json.*
import java.io.ByteArrayOutputStream
import java.nio.file.Files
import java.nio.file.Paths

@Serializable
sealed interface PdfElement {
    val id: String
}

@Serializable
@SerialName("text")
data class TextElement(
    override val id: String,
    val content: String,
    val fontSize: Int = 12,
    val fontFamily: String = "Helvetica"
) : PdfElement

@Serializable
@SerialName("image")
data class ImageElement(
    override val id: String,
    val src: String,
    val width: Int = 100,
    val height: Int = 100
) : PdfElement

@Serializable
@SerialName("template")
data class TemplateRef(
    override val id: String,
    val templatePath: String,
    val variables: Map<String, String> = emptyMap()
) : PdfElement

@Serializable
data class PdfRequest(
    val title: String,
    val elements: List<PdfElement>,
    val metadata: Map<String, String> = emptyMap()
)

class PdfRenderer(private val templateBasePath: String = "/opt/docgen/templates") {

    private val allowedFonts = setOf("Helvetica", "Times", "Courier", "Arial")
    private val maxElements = 50

    fun render(request: PdfRequest): ByteArray {
        require(request.elements.size <= maxElements) { "Too many elements" }
        val output = ByteArrayOutputStream()
        output.write("%PDF-1.4\n".toByteArray())

        for (element in request.elements) {
            renderElement(element, output)
        }

        output.write("%%EOF\n".toByteArray())
        return output.toByteArray()
    }

    private fun renderElement(element: PdfElement, output: ByteArrayOutputStream) {
        when (element) {
            is TextElement -> renderText(element, output)
            is ImageElement -> renderImage(element, output)
            is TemplateRef -> renderTemplate(element, output)
        }
    }

    private fun renderText(el: TextElement, output: ByteArrayOutputStream) {
        val sanitizedFont = if (el.fontFamily in allowedFonts) el.fontFamily else "Helvetica"
        val sanitizedSize = el.fontSize.coerceIn(6, 72)
        val escaped = el.content.replace("(", "\\(").replace(")", "\\)")
        output.write("BT /$sanitizedFont $sanitizedSize Tf ($escaped) Tj ET\n".toByteArray())
    }

    private fun renderImage(el: ImageElement, output: ByteArrayOutputStream) {
        val safeWidth = el.width.coerceIn(1, 2000)
        val safeHeight = el.height.coerceIn(1, 2000)
        // In production this would embed the image stream
        output.write("q $safeWidth 0 0 $safeHeight 0 0 cm /Img${el.id} Do Q\n".toByteArray())
    }

    private fun renderTemplate(el: TemplateRef, output: ByteArrayOutputStream) {
        val resolvedPath = resolveTemplatePath(el.templatePath)
        val templateContent = Files.readString(resolvedPath)
        var processed = templateContent
        for ((key, value) in el.variables) {
            val safeValue = value.replace("(", "\\(").replace(")", "\\)")
            processed = processed.replace("{{$key}}", safeValue)
        }
        output.write(processed.toByteArray())
    }

    private fun resolveTemplatePath(templatePath: String): java.nio.file.Path {
        val normalized = Paths.get(templateBasePath, templatePath).normalize()
        require(normalized.startsWith(templateBasePath)) { "Path traversal detected" }
        return normalized
    }
}

class ProxyHeaderParser {
    companion object {
        private val ALLOWED_CONTENT_TYPES = setOf(
            ContentType.Application.Json
        )

        fun extractContentType(headers: Headers): ContentType {
            // Ignore proxy-forwarded content type headers; always use JSON
            return ContentType.Application.Json
        }

        fun parseRequestBody(body: String, contentType: ContentType): PdfRequest {
            require(contentType.match(ContentType.Application.Json)) {
                "Only JSON content type is supported"
            }
            return Json { ignoreUnknownKeys = true }.decodeFromString<PdfRequest>(body)
        }
    }
}

fun Application.configurePdfRoutes() {
    routing {
        post("/api/v2/generate") {
            try {
                val body = call.receiveText()
                val contentType = ProxyHeaderParser.extractContentType(call.request.headers)
                val pdfRequest = ProxyHeaderParser.parseRequestBody(body, contentType)
                val renderer = PdfRenderer()
                val pdfBytes = renderer.render(pdfRequest)
                call.respondBytes(pdfBytes, ContentType("application", "pdf"))
            } catch (e: Exception) {
                // Do not leak internal exception details (file paths, stack info) to the client.
                call.application.log.warn("Failed to generate PDF", e)
                call.respondText(
                    "Invalid request",
                    status = HttpStatusCode.BadRequest
                )
            }
        }
    }
}
